import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    idx = 0
    t = int(input_data[idx])
    idx += 1

    for _ in range(t):
        k = int(input_data[idx])
        idx += 1
        n_cols = 2 * k + 1
        row1 = []
        row2 = []

        for _ in range(n_cols):
            row1.append(input_data[idx])
            idx += 1
        for _ in range(n_cols):
            row2.append(input_data[idx])
            idx += 1

        grid = [row1, row2]

        target_grid = [['' for _ in range(n_cols)] for _ in range(2)]
        for j in range(n_cols):
            target_grid[0][j] = str(j + 1)
        for j in range(n_cols - 1):
            target_grid[1][j] = str(2 * k + 2 + j)
        target_grid[1][n_cols - 1] = 'E'

        def get_state(g):
            return tuple(tuple(row) for row in g)

        def find_empty(g):
            for i in range(2):
                for j in range(n_cols):
                    if g[i][j] == 'E':
                        return i, j
            return None

        start_state = get_state(grid)
        target_state = get_state(target_grid)

        if start_state == target_state:
            print("SURGERY COMPLETE")
            print("")
            print("DONE")
            continue

        start_empty = find_empty(grid)
        target_empty = find_empty(target_grid)

        def neighbors(r, c, n_cols):
            moves = []
            if c > 0:
                moves.append(('l', r, c - 1))
            if c < n_cols - 1:
                moves.append(('r', r, c + 1))
            if r == 1 and c in (0, n_cols // 2, n_cols - 1):
                moves.append(('u', r - 1, c))
            if r == 0 and c in (0, n_cols // 2, n_cols -1):
                moves.append(('d', r + 1, c))
            return moves

        visited = {start_state: ""}
        queue = deque([start_state])
        found = False
        path = ""

        while queue and not found:
            curr = queue.popleft()
            curr_path = visited[curr]

            if curr == target_state:
                found = True
                path = curr_path
                break

            r, c = find_empty(list(map(list, curr)))
            for move_char, nr, nc in neighbors(r, c, n_cols):
                new_grid = [list(row) for row in curr]
                new_grid[r][c], new_grid[nr][nc] = new_grid[nr][nc], new_grid[r][c]
                new_state = tuple(tuple(row) for row in new_grid)

                if new_state not in visited:
                    visited[new_state] = curr_path + move_char
                    queue.append(new_state)
                    if new_state == target_state:
                        found = True
                        path = curr_path + move_char
                        break

        if not found:
            print("SURGERY FAILED")
        else:
            print("SURGERY COMPLETE")
            print(path)
            print("DONE")

solve()
